class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        def is_almost_equal(a, b):
            return abs(ord(a) - ord(b)) <= 1

        changes = 0
        i = 0
        while i < len(word) - 1:
            if is_almost_equal(word[i], word[i + 1]):
                changes += 1
                i += 2  # Skip the next character as it is already considered
            else:
                i += 1
        return changes
```

